BEGIN;SET LOCAL lock_timeout='5s';
DO $guard$ BEGIN
IF md5(pg_get_functiondef('play_claim_pass(text)'::regprocedure))<>'c560ef01e9c864c1df34c54408386192' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_claim_pass(text)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'OWNER_SUPPLY_SOURCE_OR_ACL_DRIFT';END IF;
IF md5(pg_get_functiondef('play_claim_daily_supply()'::regprocedure))<>'1329ee1367ca7c5dc85af624b3e61f48' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_claim_daily_supply()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'OWNER_SUPPLY_SOURCE_OR_ACL_DRIFT';END IF;
IF md5(pg_get_functiondef('private.pass_period_wallet(uuid)'::regprocedure))<>'a7aad9c4a03671154acbc8ee88203dd8' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pass_period_wallet(uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'OWNER_SUPPLY_SOURCE_OR_ACL_DRIFT';END IF;
END $guard$;
DO $restore$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $restore$;
DO $restore$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $restore$;
DO $restore$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $restore$;
COMMIT;
